package com.restaurant.pos.api; import org.springframework.web.bind.annotation.*; import org.springframework.security.oauth2.jwt.Jwt; import java.util.*; @RestController @RequestMapping("/api") public class MeController { @GetMapping("/me") Map<String,Object> me(@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt j){return Map.of("id",j.getSubject(),"username",j.getClaimAsString("preferred_username"),"name",j.getClaimAsString("name"),"roles",j.getClaimAsMap("realm_access"));} }
